import{_ as d,o as t,c as s,a2 as a}from"./chunks/framework.Dx-TCpNt.js";const k=JSON.parse('{"title":"构建与打包","description":"同一套代码能产出四种形态：带本地服务的浏览器版、独立服务、Electron 桌面版，以及另一个仓库里的静态在线版。本页列出命令，以及改代码时真正需要区别对待的地方。","frontmatter":{"description":"同一套代码能产出四种形态：带本地服务的浏览器版、独立服务、Electron 桌面版，以及另一个仓库里的静态在线版。本页列出命令，以及改代码时真正需要区别对待的地方。"},"headers":[],"relativePath":"zh/development/build.md","filePath":"zh/development/build.md","lastUpdated":1794821397000}'),i={name:"zh/development/build.md"};function o(c,e,n,r,l,p){return t(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="构建与打包" tabindex="-1">构建与打包 <a class="header-anchor" href="#构建与打包" aria-label="Permalink to &quot;构建与打包&quot;">​</a></h1><p>同一套代码能产出四种形态：带本地服务的浏览器版、独立服务、Electron 桌面版，以及另一个仓库里的静态在线版。本页列出命令，以及改代码时真正需要区别对待的地方。</p><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><ul><li>Node.js 22 或更新版本，配 npm。</li><li>批量 CLI 依赖 Node 的 TypeScript 支持。Node 22.6–23.5 需要加 <code>--experimental-strip-types</code>；Node 23.6 起默认开启，Node 26 可以直接跑 <code>.ts</code> 入口。</li><li>桌面打包默认面向 Windows x64（见 <code>electron-builder.yml</code>）；服务端本身在任何能跑 Node 的系统上都行。</li></ul><h2 id="命令" tabindex="-1">命令 <a class="header-anchor" href="#命令" aria-label="Permalink to &quot;命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>产物</th></tr></thead><tbody><tr><td><code>npm run dev</code></td><td>起 Vite 开发服务并挂上 API 中间件，地址 <code>127.0.0.1:5173</code>（被占用时顺延）。</td><td>无</td></tr><tr><td><code>npm run build</code></td><td>类型检查并构建前端。</td><td><code>dist/</code></td></tr><tr><td><code>npm run preview</code></td><td>用同一个 API 中间件预览构建结果。</td><td>—</td></tr><tr><td><code>npm run server:build</code></td><td>用 esbuild 打包 <code>server/app.ts</code> 与 <code>server/standalone.ts</code>。</td><td><code>dist-server/app.mjs</code>、<code>dist-server/standalone.mjs</code></td></tr><tr><td><code>npm start</code></td><td>运行打包后的独立服务。</td><td><code>127.0.0.1:3921</code></td></tr><tr><td><code>npm run desktop</code></td><td>构建、打包服务并打开 Electron。</td><td>窗口</td></tr><tr><td><code>npm run dist:win</code></td><td>生成 NSIS 安装包和便携版。</td><td><code>release/</code></td></tr><tr><td><code>npm run dist:dir</code></td><td>生成未打包目录，快速验证桌面版。</td><td><code>release/win-unpacked/</code></td></tr><tr><td><code>npm run docker:up</code></td><td>构建并运行容器，挂载本地目录。</td><td><code>http://127.0.0.1:3921</code></td></tr><tr><td><code>npm run docs:dev</code></td><td>文档站开发服务，按站点根路径访问（<code>DOCS_BASE=/</code>）。</td><td><code>127.0.0.1:5174</code></td></tr><tr><td><code>npm run docs:build</code></td><td>构建文档站，死链会让构建失败。</td><td><code>docs/.vitepress/dist/</code></td></tr></tbody></table><h2 id="本地开发" tabindex="-1">本地开发 <a class="header-anchor" href="#本地开发" aria-label="Permalink to &quot;本地开发&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>不需要另起进程：<code>server/plugin.ts</code> 把 <code>createMangaHandler</code> 挂成 Vite 中间件，<code>configureServer</code> 和 <code>configurePreviewServer</code> 都覆盖了。所以 <code>/api/library</code> 和页面在同一个事件循环里处理，服务端的 <code>console.log</code> 就打在跑 Vite 的那个终端里。</p><p>前端由 Vite 从 <code>src/</code> 提供；服务端按仓库根目录读写 <code>raw/</code> 和 <code>data/</code>。</p><h2 id="生产构建" tabindex="-1">生产构建 <a class="header-anchor" href="#生产构建" aria-label="Permalink to &quot;生产构建&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p><code>npm run build</code> 先跑 <code>tsc -b</code>，有类型错误就直接失败。<code>server:build</code> 以 <code>platform: node</code>、<code>format: esm</code>、<code>target: node20</code> 打包，并注入 <code>createRequire</code> 头，因为 <code>pngjs</code> 和 <code>jpeg-js</code> 内部仍会调用 <code>require</code>。</p><p><code>npm start</code> 要求 <code>dist/</code> 已存在，否则 <code>server/standalone.ts</code> 会以 <code>CLI_MISSING_STATIC_DIR</code> 退出。配置全部走环境变量：</p><table tabindex="0"><thead><tr><th>变量</th><th>默认值</th><th>用途</th></tr></thead><tbody><tr><td><code>HOST</code></td><td><code>127.0.0.1</code></td><td>监听地址。仅在需要局域网访问时设为 <code>0.0.0.0</code>；本服务没有登录鉴权。</td></tr><tr><td><code>PORT</code></td><td><code>3921</code></td><td>监听端口。</td></tr><tr><td><code>RAW_DIR</code></td><td><code>&lt;cwd&gt;/raw</code></td><td>漫画图片目录。</td></tr><tr><td><code>DATA_DIR</code></td><td><code>&lt;cwd&gt;/data</code></td><td>JSON 数据目录。</td></tr><tr><td><code>EXPORT_DIR</code></td><td><code>&lt;cwd&gt;/exports</code></td><td>生成文件目录。</td></tr><tr><td><code>STATIC_DIR</code></td><td><code>&lt;cwd&gt;/dist</code></td><td>构建后的前端。</td></tr><tr><td><code>MANGA_LOCALE</code></td><td>自动</td><td>界面语言提示：<code>en</code>、<code>zh</code>、<code>ja</code>。</td></tr><tr><td><code>LOG_LEVEL</code></td><td><code>info</code></td><td><code>debug</code>、<code>info</code>、<code>warn</code>、<code>error</code>。</td></tr></tbody></table><h2 id="桌面版" tabindex="-1">桌面版 <a class="header-anchor" href="#桌面版" aria-label="Permalink to &quot;桌面版&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist:win</span></span></code></pre></div><p><code>electron/main.cjs</code> 在进程内加载 <code>dist-server/app.mjs</code>，提供 <code>dist/</code> 并打开窗口。数据不会打进安装包：首次启动会要求选择图库目录，并记在 <code>%APPDATA%/manga-memo/config.json</code>，<code>raw/</code>、<code>data/</code>、<code>exports/</code> 仍留在你自己的目录里。</p><p>打包配置在 <code>electron-builder.yml</code>。只会打包 <code>dist/</code>、<code>dist-server/</code>、<code>electron/</code> 和 <code>package.json</code>；服务端已经把自己的依赖打进去了，因此不附带 <code>node_modules</code>。</p><h2 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre></div><p>容器运行 <code>dist-server/standalone.mjs</code>，从宿主机挂载 <code>raw/</code>、<code>data/</code>、<code>exports/</code>。它是给本机用的：没有账号也没有鉴权，不要把端口暴露到公网。</p><h2 id="静态在线版" tabindex="-1">静态在线版 <a class="header-anchor" href="#静态在线版" aria-label="Permalink to &quot;静态在线版&quot;">​</a></h2><p>静态在线版是另一个项目：<code>https://github.com/PayayaKamo/KomaYomi-online</code>，只保留浏览器能跑的那部分。它共用页面格式和工程文件读取，但无法扫描目录、做分格检测、加载插件或连接 WebDAV，因为这些都离不开服务端进程。在那里保存的内容放在 IndexedDB。</p><p>新增功能时先想清楚它属于哪种形态：</p><table tabindex="0"><thead><tr><th>改动</th><th>本地服务版</th><th>静态在线版</th></tr></thead><tbody><tr><td>页面文档新增字段</td><td>改 <code>shared/</code> 和服务端规范化逻辑。</td><td>只要逻辑在 <code>shared/</code> 里就能用。</td></tr><tr><td>新增检测器或插件钩子</td><td><code>server/detect.ts</code>、<code>server/plugins.ts</code>。</td><td>不可用。</td></tr><tr><td>新增对话框或视图</td><td><code>src/components/</code>。</td><td>只调用现有 API 的话通常可移植。</td></tr><tr><td>文件系统、进程或网络访问</td><td>仅服务端。</td><td>不可用。</td></tr></tbody></table><h2 id="更新检测基线" tabindex="-1">更新检测基线 <a class="header-anchor" href="#更新检测基线" aria-label="Permalink to &quot;更新检测基线&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/manga-cli.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> regress</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/manga-cli.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> regress</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --update</span></span></code></pre></div><p>第一条命令把当前分格数量与 <code>scripts/detect-baseline.json</code> 对比；<code>--update</code> 重写基线。提交前先看 diff——更新基线等于承诺新数量是对的。</p><h2 id="提-pr-之前" tabindex="-1">提 PR 之前 <a class="header-anchor" href="#提-pr-之前" aria-label="Permalink to &quot;提 PR 之前&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i18n:scan</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p><code>i18n:scan</code> 默认非严格；CI 会把 <code>src/</code> 里新增的写死中文当作失败。<code>docs:build</code> 遇到死链会失败，这是发现三语页面改名遗漏最省事的办法。</p>`,32)])])}const F=d(i,[["render",o]]);export{k as __pageData,F as default};
